function streak(){let count=0,cursor=date(today);for(let guard=0;guard<366;guard++){const day=key(cursor),progress=dayProgress(day);if(progress.due.length&&progress.rate===100)count++;else if(progress.due.length)break;cursor.setDate(cursor.getDate()-1);}return count;}
