function exportData(){const payload={version:2,exportedAt:new Date().toISOString(),account:currentUser?{name:currentUser.name,email:currentUser.email}:null,habits,journals:journalStore()};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:"application/json"})),a=document.createElement("a");a.href=url;a.download=`habitflow-backup-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Backup downloaded.");}
function cleanImportedJournals(value){if(!value||typeof value!=="object"||Array.isArray(value))return null;const cleaned={};Object.entries(value).forEach(([entryDate,entry])=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(entryDate)||!entry||typeof entry!=="object"||Array.isArray(entry))return;cleaned[entryDate]={mood:String(entry.mood||"").slice(0,40),wins:String(entry.wins||"").slice(0,10000),challenges:String(entry.challenges||"").slice(0,10000),improvement:String(entry.improvement||"").slice(0,10000),updatedAt:String(entry.updatedAt||"")};});return cleaned;}
