function saveGoal(e){e.preventDefault();const title=document.querySelector("#goal-title").value.trim();if(!title)return;const item=document.createElement("article");item.className="habit-card";item.innerHTML=`<h3>${esc(title)}</h3><p class="habit-card-description">${esc(document.querySelector("#goal-description").value||"A goal worth working toward.")}</p><p class="habit-card-description">Target: ${esc(document.querySelector("#goal-deadline").value||"No deadline")}</p>`;document.querySelector("#goals-list")?.prepend(item);e.target.reset();toast("Goal saved.");}
function saveJournal(e){e.preventDefault();const entry={mood:document.querySelector("#journal-mood")?.value||"",wins:document.querySelector("#journal-wins")?.value.trim()||"",challenges:document.querySelector("#journal-challenges")?.value.trim()||"",improvement:document.querySelector("#journal-improvement")?.value.trim()||"",updatedAt:new Date().toISOString()};const store=journalStore();store[journalDate]=entry;if(!saveJournalStore(store)){text("#journal-save-status","Could not save on this device.");return toast("Your journal could not be saved.");}text("#journal-save-status","Saved on this device just now.");renderJournalHistory();toast("Journal entry saved locally.");}
