function renderJournalHistory(){const list=document.querySelector("#journal-history-list");if(!list)return;const query=(document.querySelector("#journal-history-search")?.value||"").trim().toLowerCase(),entries=Object.entries(journalStore()).filter(([entryDate,entry])=>{const haystack=`${entryDate} ${entry.mood||""} ${entry.wins||""} ${entry.challenges||""} ${entry.improvement||""}`.toLowerCase();return !query||haystack.includes(query)}).sort(([a],[b])=>b.localeCompare(a));text("#journal-history-count",`${entries.length} saved`);if(!entries.length){list.innerHTML=`<div class="journal-history-empty">${query?"No reflections match your search.":"Your saved reflections will appear here."}</div>`;return;}list.innerHTML=entries.map(([entryDate,entry])=>{const preview=entry.wins||entry.challenges||entry.improvement||"No written notes yet.";return `<button type="button" class="journal-history-item ${entryDate===journalDate?"selected":""}" data-journal-date="${esc(entryDate)}"><span><strong>${esc(fmt(entryDate,{weekday:"short",month:"short",day:"numeric",year:"numeric"}))}</strong><small>${esc(entry.mood?`Mood: ${entry.mood}`:"Reflection")}</small></span><em>${esc(preview.slice(0,90))}${preview.length>90?"…":""}</em></button>`;}).join("");}
