function bindAuthentication(){
  document.querySelector("#login-tab")?.addEventListener("click",()=>showAuthPanel("login"));
  document.querySelector("#register-tab")?.addEventListener("click",()=>showAuthPanel("register"));
  document.querySelector("#login-panel")?.addEventListener("submit",loginUser);
  document.querySelector("#register-panel")?.addEventListener("submit",registerUser);
  document.querySelector("#forgot-password-button")?.addEventListener("click",()=>showAuthPanel("recovery"));
  document.querySelector("#back-to-login")?.addEventListener("click",()=>showAuthPanel("login"));
  document.querySelector("#recovery-panel")?.addEventListener("submit",resetLocalPassword);
}
function clearAuthMessages(){["#login-message","#register-message","#recovery-message"].forEach(selector=>text(selector,""));}
function showAuthPanel(panel){clearAuthMessages();["login","register","recovery"].forEach(name=>{const form=document.querySelector(`#${name}-panel`),tab=document.querySelector(`#${name}-tab`);if(form)form.hidden=name!==panel;if(tab){tab.classList.toggle("active",name===panel);tab.setAttribute("aria-selected",String(name===panel));}});const focusTarget=document.querySelector(`#${panel}-panel input`);if(focusTarget)requestAnimationFrame(()=>focusTarget.focus());}
function setSignedIn(user,options={}){currentUser=normalizeUser(user);if(!currentUser)return;saveLocal(SESSION_KEY,{id:currentUser.id,name:currentUser.name,email:currentUser.email,googleId:currentUser.googleId});writeLocal("habitflow.profile",currentUser.name);if(options.migrateGuest)migrateGuestJournals(currentUser);const historySearch=document.querySelector("#journal-history-search");if(historySearch)historySearch.value="";text("#profile-name",currentUser.name);text("#settings-name",currentUser.name);text("#settings-email",currentUser.email);text("#profile-email",currentUser.email);text("#account-status",`Signed in as ${currentUser.email}`);text("#account-status-note","Your journal is saved locally for this account on this device.");const initials=currentUser.name.split(/\s+/).map(word=>word[0]).join("").slice(0,2).toUpperCase();text("#profile-avatar",initials);text("#topbar-avatar",initials);document.querySelector("#account-login-button")?.setAttribute("hidden","");document.querySelector("#account-create-button")?.setAttribute("hidden","");document.querySelector("#logout-button")?.removeAttribute("hidden");document.querySelector("#app").hidden=false;document.querySelector("#auth-screen").hidden=true;loadJournal();}
function migrateGuestJournals(user){const guest=journalStore(null),existing=journalStore(user);if(Object.keys(guest).length&&!Object.keys(existing).length)saveJournalStore(guest,user);}
function signOut(){currentUser=null;removeLocal(SESSION_KEY);document.querySelector("#account-login-button")?.removeAttribute("hidden");document.querySelector("#account-create-button")?.removeAttribute("hidden");document.querySelector("#logout-button")?.setAttribute("hidden","");document.querySelector("#app").hidden=true;document.querySelector("#auth-screen").hidden=false;showAuthPanel("login");toast("You have been logged out.");}
function restoreSession(){const saved=normalizeUser(load(SESSION_KEY,null));if(saved)setSignedIn(saved);else{currentUser=null;document.querySelector("#app").hidden=false;document.querySelector("#auth-screen").hidden=true;document.querySelector("#logout-button")?.setAttribute("hidden","");updateAccountStatus();}}
async function passwordHash(password){if(globalThis.crypto?.subtle){const bytes=new TextEncoder().encode(password),buffer=await crypto.subtle.digest("SHA-256",bytes);return Array.from(new Uint8Array(buffer)).map(byte=>byte.toString(16).padStart(2,"0")).join("");}return btoa(password);}
function validPassword(password){return password.length>=8&&/[A-Za-z]/.test(password)&&/\d/.test(password);}
async function registerUser(e){e.preventDefault();clearAuthMessages();const name=document.querySelector("#register-name").value.trim(),email=document.querySelector("#register-email").value.trim().toLowerCase(),password=document.querySelector("#register-password").value,confirmPassword=document.querySelector("#register-confirm-password").value,terms=document.querySelector("#accept-terms")?.checked,users=load(USERS_KEY,[]);if(name.length<2)return text("#register-message","Please enter your name.");if(!/^\S+@\S+\.\S+$/.test(email))return text("#register-message","Enter a valid email address.");if(!validPassword(password))return text("#register-message","Use at least 8 characters, including a letter and a number.");if(password!==confirmPassword)return text("#register-message","Passwords do not match.");if(!terms)return text("#register-message","Please accept the terms to continue.");if(users.some(user=>String(user.email||"").toLowerCase()===email))return text("#register-message","An account with this email already exists. Try logging in.");const user={id:`email:${email}`,name,email,passwordHash:await passwordHash(password)};users.push(user);if(!saveLocal(USERS_KEY,users))return text("#register-message","This browser blocked local storage. Account not created.");setSignedIn(user,{migrateGuest:true});toast("Account created successfully.");}
async function loginUser(e){e.preventDefault();clearAuthMessages();const email=document.querySelector("#login-email").value.trim().toLowerCase(),password=document.querySelector("#login-password").value;if(!email||!password)return text("#login-message","Enter your email and password.");const passwordHashValue=await passwordHash(password),user=load(USERS_KEY,[]).map(normalizeUser).find(item=>item?.email===email&&item.passwordHash===passwordHashValue);if(!user)return text("#login-message","Email or password is incorrect.");setSignedIn(user);toast("Welcome back.");}
