async function loadGoogleConfig(){try{const response=await fetch("/api/config");if(response.ok){const config=await response.json();googleClientId=config.googleClientId||googleClientId;}}catch{} }
function googleSignIn(){if(!googleClientId)return toast("Configure GOOGLE_CLIENT_ID before using Google sign-in.");if(!window.google){const script=document.createElement("script");script.src="https://accounts.google.com/gsi/client";script.onload=googleSignIn;script.onerror=()=>toast("Google sign-in could not load.");document.head.appendChild(script);return;}google.accounts.id.initialize({client_id:googleClientId,callback:handleGoogleCredential});google.accounts.id.prompt();}
function handleGoogleCredential(response){try{const payload=JSON.parse(atob(response.credential.split(".")[1].replace(/-/g,"+").replace(/_/g,"/")));if(!payload.email)return toast("Google did not provide an email address.");setSignedIn({name:payload.name||payload.email.split("@")[0],email:payload.email,googleId:payload.sub});toast("Signed in with Google.");}catch{toast("Google sign-in could not be completed.");}}
